# find repeated substrings
from collections import defaultdict
def rep(k):
    d=defaultdict(list)
    for i in range(len(seq)-k+1): d[seq[i:i+k]].append(i)
    return [(kmer,p) for kmer,p in d.items() if len(p)>1]
